php:odata.template:
// OData: get one entity by key
$result = $bridge->getODataRecord('{{php:recordId}}', [
    'table' => '{{php:resource}}',
]);

javascript:data-api.template:
// Browser-safe read: ask the protected PHP bridge for one Data API record.
const response = await fetch('/openbridge-api.php', {
  method: 'POST',
  credentials: 'include',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    action: 'playground',
    transport: 'data-api',
    operation: 'get',
    resource: {{js:resource}},
    recordId: {{js:recordId}},
  }),
});

const result = await response.json();

